from langflow.custom import CustomComponent
from langchain.tools import Tool
import requests

class DallETool(CustomComponent):
    display_name = "DALL-E 3 Generator"
    description = "Generates an image from a text prompt using OpenAI DALL-E 3."

    def build_config(self):
        return {
            "api_key": {
                "display_name": "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",
                "password": True,
            }
        }

    # FIX: Added **kwargs here to prevent the "unexpected argument" crash
    def build(self, api_key: str, **kwargs) -> Tool:

        def generate_image(prompt: str) -> str:
            # 1. Prepare the API Call
            url = "https://api.openai.com/v1/images/generations"
            headers = {
                "Content-Type": "application/json",
                "Authorization": f"Bearer {api_key}"
            }
            data = {
                "model": "dall-e-3",
                "prompt": prompt,
                "n": 1,
                "size": "1024x1024"
            }

            # 2. Execute
            try:
                response = requests.post(url, headers=headers, json=data)
                result = response.json()

                if "error" in result:
                    return f"OpenAI Error: {result['error']['message']}"

                # 3. Success - Return the image URL in Markdown format
                url = result['data'][0]['url']
                return f"![Generated Image]({url})"

            except Exception as e:
                return f"Connection Failed: {str(e)}"

        # 4. Return the Tool to the Agent
        return Tool(
            name="generate_image",
            description="Useful for generating images. Input should be a detailed visual description.",
            func=generate_image
        )

from langflow.custom import CustomComponent
from langchain.tools import Tool

class FileSaver(CustomComponent):
    display_name = "File Saver Tool"
    description = "A tool to save text to a local file."

    def build_config(self):
        return {
            "file_path": {"display_name": "File Name", "value": "comic_history.txt"},
        }

    # FIX: Added **kwargs to prevent the crash
    def build(self, file_path: str, **kwargs) -> Tool:

        def save_to_file(content: str) -> str:
            try:
                # Open in 'append' mode (a) so we keep history
                with open(file_path, "a", encoding="utf-8") as f:
                    f.write("\n\n" + "="*30 + "\n")
                    f.write(content)
                return f"Successfully saved to {file_path}"
            except Exception as e:
                return f"Failed to save: {str(e)}"

        return Tool(
            name="save_comic",
            description="Use this tool to save the final script. Input should be the text content.",
            func=save_to_file
        )
